module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

    reg [15:0] a_reg;
    reg [15:0] b_reg;

    always @(*) begin
        a_reg = A;
        b_reg = {8'b0, B};
    end

    always @(*) begin
        result = 0;
        odd = 0;
        reg [15:0] temp_a;
        reg [15:0] temp_b;
        reg [15:0] quotient;
        reg [15:0] remainder;

        temp_a = a_reg;
        temp_b = b_reg;

        for (int i = 0; i < 16; i = i + 1) begin
            if (temp_a >= temp_b) begin
                quotient = quotient | (1 << i);
                temp_a = temp_a - temp_b + 1;
            end else begin
                quotient = quotient & ~(1 << i);
            end
            temp_b = temp_b << 1;
        end

        result = quotient;
        odd = temp_a;
    end

endmodule

